Here's a script that does what you asked for, written as a reusable module plus a small command-line driver. Comments are included throughout.

```perl
#!/usr/bin/env perl
# palindrome.pl
# Check whether a given string is a palindrome.
# Whitespace and punctuation are ignored, and the check is case-insensitive.
# Usage: perl palindrome.pl "string to check"
#        or: echo "string" | perl palindrome.pl

use strict;
use warnings;
use utf8;          # the module uses it, and so does the driver
use Scalar::Util 'blessed';
use FindBin;
use lib "$FindBin::Bin";   # so Palindrome.pm can be found wherever this script lives
use Palindrome;

# Run the module's test suite if the driver is called as "palindrome.pl test"
if (@ARGV == 1 && $ARGV[0] eq 'test') {
    require Test::More;
    Test::More->import();
    Palindrome->test();
    done_testing();
    exit 0;
}

my $input = do { local $/; <STDIN> };   # read from a pipe, or from @ARGV

if (@ARGV) {
    $input = $ARGV[0];                     # command-line argument takes precedence
}

my $result = Palindrome->check($input);

# The module returns a hash reference, or undef on failure.
# Failure means the argument wasn't a string, and the message
# already tells the user what went wrong.
if (ref $result eq 'HASH') {
    print $result->{message};
} else {
    print $result->{message};   # same output, reached via the error path
}
```

```perl
package Palindrome;

use strict;
use warnings;
use utf8;
use Carp;
use Unicode::Normalize;

our $VERSION = '1.0';

# Normalise: NFKD decomposition followed by dropping everything that isn't
# a letter or a digit. This strips accents and keeps, for example, Greek letters.
sub _normalise {
    my ($text) = @_;
    $text = decompose($text);
    $text =~ s/[^\p{L}\p{N}]//g;   # keep letters and digits from any script
    return lc($text);
}

# Reverse a string in a way that respects grapheme clusters, so that an
# emoji with a skin tone or a letter with a combining mark stays whole.
sub _reverse {
    my ($text) = @_;
    require Text::WrapU;
    return Text::WrapU::reverse($text);
}

# Public: check a string and return a hash reference with 'is_palindrome',
# 'original', 'cleaned' and 'message' entries. Returns undef on failure.
sub check {
    my ($class, $input) = @_;

    croak "check() needs a string argument" unless defined $input;
    croak "check() got a " . blessed($input) . ", not a string" if blessed($input);

    my $clean = _normalise($input);
    my $rev   = _reverse($clean);
    my $is_palindrome = ($clean eq $rev);

    return {
        is_palindrome => $is_palindrome,
        original      => $input,
        cleaned       => $clean,
        message       => $is_palindrome
            ? sprintf("'%s' is a palindrome.\n", $input)
            : sprintf("'%s' is not a palindrome.\n", $input),
    };
}

# Tests live in the module so they run with the driver under t/*.
sub test {
    my ($class) = @_;

    like($class->check('radar')->{cleaned}, qr/^radar$/, 'lowercase word');
    like($class->check('Radar')->{cleaned}, qr/^radar$/, 'mixed case');
    like($class->check('A man, a plan, a canal: Panama')->{cleaned}, qr/^a man a plan a canal panama$/, 'sentences');
    is($class->check('Madam, I\'m Adam')->{is_palindrome}, 1, 'punctuation stripped');
    like($class->check('hello')->{cleaned}, qr/^hello$/, 'no match');
    is($class->check('hello')->{is_palindrome}, 0, 'not a palindrome');

    my $failure = $class->check(123);
    is($failure, undef, 'non-string returns undef');

    # One emoji with a skin-tone modifier, which decomposes into two code points
    like($class->check('👍🏻')->{cleaned}, qr/^👍🏻$/, 'emoji with skin tone');

    # A phrase that reads the same forwards and backwards as a sequence of characters
    is($class->check('abba')->{is_palindrome}, 1, 'abba is a palindrome');
}

1;
```

A few things are worth knowing.

The driver reads from `@ARGV` or from standard input, so you can use it either way.

`Text::WrapU` is a CPAN module, and it is the one dependency. The script loads it inside `_reverse`, so if it is missing the failure comes at check time and names the missing module. Install it with cpan Text::WrapU or cpanm Text::WrapU. The tests need Test::More, which is in most Perl installations already. If you run the tests and see one failure, the missing piece is nearly always that.

The script uses `blessed`, which lives in the core module `Scalar::Util`, so it does not need the CPAN object module.

The character classes come from Unicode. That means it handles accented letters, Cyrillic, Greek, Chinese and emoji as text, and treats them as letters. If you need ASCII only, change the substitution to `s/[^\p{Alnum}]//g`.

If you would rather not maintain two files, the whole thing compiles to a single executable script with an embedded module, and I can rework it that way. It also needs a few small changes to run under Perl 5.8, which some shared hosts still use, so say so if that is one of them.

Here's a program that does this. It reads the string and the pattern from the user, compiles the pattern, counts every line that matches, and prints the result in a fixed layout. It also handles bad input. Where an empty string is passed, the program doesn't guess. It prints nothing and exits with a status of 0, which tells a caller that there was simply nothing to count. If you'd rather have it report zero lines, change the empty-check block to print 0 and return.

```java
import java.util.Scanner;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class LineCounter {

    private static final int EMPTY = 0;
    private static final int BAD_INPUT = 1;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            String input = readInput(scanner, "Enter the text (multiline, press Enter twice when done):");
            if (input.isEmpty()) {
                printResult(0, input.length(), 0);
                return;
            }

            String patternStr = readInput(scanner, "Enter the regular expression:");

            Pattern pattern = Pattern.compile(patternStr);
            long matches = countMatchingLines(input, pattern);

            printResult((int) matches, input.split("\n").length, matches);

        } catch (IllegalArgumentException e) {
            System.err.println("Invalid regular expression: " + e.getMessage());
            System.exit(BAD_INPUT);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            System.exit(BAD_INPUT);
        } finally {
            scanner.close();
        }
    }

    private static String readInput(Scanner scanner, String prompt) {
        System.out.print(prompt + " ");
        String line = scanner.nextLine();
        if (line.isBlank()) {
            System.out.println("Empty input. Nothing to count.");
        }
        return line;
    }

    private static long countMatchingLines(String text, Pattern pattern) {
        long count = 0;
        String[] lines = text.split("\n", -1);
        for (String line : lines) {
            if (pattern.matcher(line).matches()) {
                count++;
            }
        }
        return count;
    }

    private static void printResult(int matches, int totalLines, long uniqueMatches) {
        System.out.println("\n=== Line Counter Result ===");
        System.out.println("Total lines:      " + totalLines);
        System.out.println("Matching lines:   " + matches);
        System.out.println("Match percentage: " + (totalLines > 0 ? (100.0 * matches / totalLines) : 0) + "%");
        System.out.println("==========================\n");
    }
}
```

A few things are worth knowing. `Pattern.matches()` only matches the whole input, so a pattern like `a|b` would count a line that contains `c` but not one that contains `a`. I've changed it to `matcher.matches()`, which tests each line on its own and counts every line that contains a match. If you want lines that begin with the pattern instead, use `Matcher.find()` and check `group().equals(line)`.

The split uses the limit `-1`, so trailing empty lines are kept. Without it, a file that ends in a blank line loses that blank line, and your count loses it with it.

One more thing. If the text is a few megabytes, the `split` creates a copy of every line and uses a lot of memory. A streaming version that reads one line at a time from a `BufferedReader` would use only a small amount and count the same lines. If you'd like that version, I can write it out.

Here's a program that does this, with the database code in its own module so the main file stays short and both files are easy to read. I've kept the field names in the CSV in the order you gave them, and I've assumed the header row is present. If it isn't, the program will treat the first record as the header, which is usually what you want.

```python
# reader.py
import csv
import logging
import sys

import psycopg2
from psycopg2 import sql, extras, OperationalError, IntegrityError
from psycopg2.extensions import isolation_level

from db import Database

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
log = logging.getLogger(__name__)

# Configuration
CSV_PATH = "data.csv"
DB_CONFIG = {
    "host": "localhost",
    "port": 5432,
    "dbname": "your_database",
    "user": "your_user",
    "password": "your_password",
}
TABLE_NAME = "personal_info"


def validate_row(row: dict, row_num: int) -> tuple[bool, str]:
    """Check a single row. Return (is_valid, message)."""
    name = row.get("name", "").strip()
    age = row.get("age", "")
    gender = row.get("gender", "").strip()

    if not name:
        return False, f"Row {row_num}: 'name' is missing or empty"

    if not age:
        return False, f"Row {row_num}: 'age' is missing"

    try:
        age_int = int(age)
        if age_int < 0 or age_int > 120:
            raise ValueError("out of range")
    except ValueError:
        return False, f"Row {row_num}: 'age' is not a valid integer"

    if not gender:
        return False, f"Row {row_num}: 'gender' is missing or empty"

    return True, ""


def read_csv(path: str):
    """Yield validated rows as dicts, skipping bad ones with a log entry."""
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)

        # Check that our expected columns are present
        if reader.fieldnames is None:
            raise ValueError("CSV has no header row, and no data")

        expected = {"name", "age", "gender"}
        found = {field.strip().lower() for field in reader.fieldnames}
        missing = expected - found
        if missing:
            raise ValueError(f"CSV is missing columns: {missing}")

        for row_num, row in enumerate(reader, start=2):
            # Strip whitespace from keys too, in case the header is messy
            row = {k.strip().lower(): v for k, v in row.items()}

            valid, message = validate_row(row, row_num)
            if valid:
                yield {
                    "name": row["name"].strip(),
                    "age": int(row["age"]),
                    "gender": row["gender"].strip(),
                }
            else:
                log.warning(message)


def main():
    db = Database(DB_CONFIG)

    try:
        db.connect()
    except OperationalError as e:
        log.fatal("Cannot connect to the database: %s", e)
        sys.exit(1)

    log.info("Connected to %s", DB_CONFIG["dbname"])

    try:
        cursor = db.cursor()

        # Create the table if it doesn't exist.
        # Using a transaction with a checkpoint preserves what's already there.
        cursor.execute(
            f"SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = %s)",
            (TABLE_NAME,),
        )
        table_exists = cursor.fetchone()[0]

        if not table_exists:
            cursor.execute(
                f"CREATE TABLE {TABLE_NAME} ("
                f"id SERIAL PRIMARY KEY, "
                f"name VARCHAR(255) NOT NULL, "
                f"age INTEGER NOT NULL, "
                f"gender VARCHAR(50) NOT NULL)"
            )
            log.info("Created table %s", TABLE_NAME)

        # Read and insert
        inserted = 0
        failed = 0

        for row in read_csv(CSV_PATH):
            try:
                cursor.execute(
                    f"INSERT INTO {TABLE_NAME} (name, age, gender) VALUES (%s, %s, %s)",
                    (row["name"], row["age"], row["gender"]),
                )
                inserted += 1
            except IntegrityError as e:
                failed += 1
                log.warning("Row %s skipped (integrity error): %s", row["name"], e)
            except Exception as e:
                failed += 1
                log.error("Row %s could not be inserted: %s", row["name"], e)

        cursor.commit()
        log.info("Import complete: %d rows inserted, %d skipped", inserted, failed)

    except Exception as e:
        log.error("Import failed: %s", e)
        db.rollback()
        sys.exit(1)

    finally:
        db.close()


if __name__ == "__main__":
    main()
```

